/** Domain error for milestone state conflicts (closed, already open, cap, name clash). */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: "closed" | "already_open" | "too_many_open" | "name_taken",
    message?: string,
  ) {
    super(message ?? `Milestone conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}
