/**
 * Milestone rows and their issue membership. Every method takes `orgId` first.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { toIssue, toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of the project, closed ones included, oldest first. */
export async function listProjectMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  return getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(milestones.createdAt, milestones.id)
    .all()
    .map(toMilestone);
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function patchMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
    closedAt?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .returning()
    .get();
  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setIssueMilestoneId(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: MilestoneId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();
  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Live issues of a milestone, any status. */
export async function listLiveMilestoneIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<readonly Issue[]> {
  return getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.milestoneId, milestoneId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .all()
    .map((row) => toIssue(row));
}

/** Moves the given issues to another milestone (or none) in one statement. */
export async function moveIssuesToMilestone(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  milestoneId: MilestoneId | null,
): Promise<void> {
  if (issueIds.length === 0) return;
  getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])))
    .run();
}

export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneProgress> {
  const live = await listLiveMilestoneIssues(orgId, milestoneId);
  const closed = live.filter((issue) =>
    CLOSED_ISSUE_STATUSES.includes(issue.status),
  ).length;
  return { total: live.length, open: live.length - closed, closed };
}
