cat > server/services/milestone-service.ts <<'EOF'
/**
 * Milestone business rules: authorization, name uniqueness, the open cap, progress and the close/reopen lifecycle.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, notify
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import { actorEnvelope, projectResource, requireFound } from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

const normalizeName = (name: string): string => name.trim().toLowerCase();

async function loadProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<readonly Milestone[]> {
  const all = await milestoneRepo.listProjectMilestones(orgId, projectId);
  const wanted = normalizeName(name);
  if (all.some((m) => m.id !== exceptId && normalizeName(m.name) === wanted)) {
    throw new MilestoneStateError("name_taken", `Milestone name "${name}" is taken`);
  }
  return all;
}

function assertRoomForOpen(all: readonly Milestone[]): void {
  if (
    all.filter((m) => m.closedAt === null).length >=
    MAX_OPEN_MILESTONES_PER_PROJECT
  ) {
    throw new MilestoneStateError(
      "too_many_open",
      `A project holds at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`,
    );
  }
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const all = await assertNameFree(input.orgId, project.id, input.name, null);
  assertRoomForOpen(all);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name.trim(),
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });
  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.name !== undefined) {
    await assertNameFree(input.orgId, project.id, input.name, milestone.id);
  }

  return milestoneRepo.patchMilestone(input.orgId, milestone.id, {
    ...(input.name === undefined ? {} : { name: input.name.trim() }),
    ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundErrorFor(targetId);
    }
    const target = await milestoneRepo.findMilestoneById(input.orgId, targetId);
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundErrorFor(targetId);
    }
    if (target.closedAt !== null) throw new MilestoneStateError("closed");
  }

  const live = await milestoneRepo.listLiveMilestoneIssues(
    input.orgId,
    milestone.id,
  );
  const moved = live.filter((issue) => !CLOSED_ISSUE_STATUSES.includes(issue.status));
  const movedIssueIds = moved.map((issue) => issue.id);

  await milestoneRepo.moveIssuesToMilestone(input.orgId, movedIssueIds, targetId);
  const closed = await milestoneRepo.patchMilestone(input.orgId, milestone.id, {
    closedAt: toIsoTimestamp(new Date()),
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  for (const issue of moved) {
    if (issue.assigneeId === null) continue;
    await notify(input.orgId, "issue_milestone_changed", [issue.assigneeId], {
      title: "An issue changed milestone",
      body: `Issue ${issue.id} moved because milestone ${closed.name} was closed`,
      href: `/issues/${issue.id}`,
      actorId: actor.userId,
    });
  }

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");
  assertRoomForOpen(await milestoneRepo.listProjectMilestones(orgId, project.id));

  const reopened = await milestoneRepo.patchMilestone(orgId, milestone.id, {
    closedAt: null,
  });
  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });
  return reopened;
}

async function withProgress(
  milestone: Milestone,
  now: number,
): Promise<MilestoneWithProgress> {
  const progress = await milestoneRepo.getMilestoneProgress(
    milestone.orgId,
    milestone.id,
  );
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    new Date(milestone.targetDate).getTime() < now &&
    progress.open > 0;
  return { milestone, progress, overdue };
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = Date.now();
  const all = await milestoneRepo.listProjectMilestones(orgId, projectId);
  const time = (m: Milestone): number =>
    m.targetDate === null ? Number.POSITIVE_INFINITY : new Date(m.targetDate).getTime();

  const sorted = [...all].sort((a, b) => {
    const group = Number(a.closedAt !== null) - Number(b.closedAt !== null);
    if (group !== 0) return group;
    const ta = time(a);
    const tb = time(b);
    if (ta !== tb) return ta < tb ? -1 : 1;
    if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
    return 0;
  });

  return Promise.all(sorted.map((m) => withProgress(m, now)));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));
  return withProgress(milestone, Date.now());
}
